import{z as n,x as p,o as e,c as C,q as l,j as A,D as E,d as t,s as r,S as s,b as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"全芯片仿真的计算量","description":"","frontmatter":{"title":"全芯片仿真的计算量","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/full-chip-simulation-cost.md","filePath":"litho/full-chip-simulation-cost.md","lastUpdated":1791413859000}'),d={name:"litho/full-chip-simulation-cost.md"};function B(m,a,h,D,c,u){const i=p("Mermaid");return e(),C("div",null,[a[2]||(a[2]=l('<h1 id="全芯片仿真的计算量" tabindex="-1">全芯片仿真的计算量 <a class="header-anchor" href="#全芯片仿真的计算量" aria-label="Permalink to &quot;全芯片仿真的计算量&quot;">​</a></h1><div class="epigraph"><p>全芯片要的不是麦克斯韦处处真解，是在签核期限里把每一条可印边扫完；算力合同决定谁进内循环、谁只能抽热区。</p><footer>—— 对照计算光刻对全芯片前向成本的公开讨论；紧凑对严格见 Wong / Erdmann 传统</footer></div><p><a href="/litho/etch-model-calibration">上一课</a>把光学–胶–刻蚀收成可调用核。缺口是墙钟：同一条核扫完全场要多少机时，从而 OPC 内循环、LRC 抽检和实验室 3D 各占哪一层。<a href="/litho/compact-vs-rigorous">紧凑对严格</a> 已声明分工；本课钉数量级，不重写 FDTD。<a href="/litho/lfd">光刻友好设计</a> 下一课才问：设计侧如何少制造必须仿真的坏图形。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一片 26 mm × 33 mm 的场，纳米级边长、多重曝光与 PV-band 点，把严格电磁当 OPC 内核会把周期拉到不可交货。<a href="/litho/fdtd-mask">FDTD 掩模</a> 与 <a href="/litho/rcwa">RCWA</a> 是老师，不是每晚全场引擎。紧凑核（TCC 卷积、CM 胶、密度刻蚀）把每碎片变成可并行的滤波；即便如此，高 NA、曲线 ILT、多过程角仍把集群打满。</p><p>缺口是<strong>谁付算力</strong>，不是再推一次成像积分。把「全芯片严格」写进签核清单，等于没有签核日期。</p><h3 id="三层前向-三张账单" tabindex="-1">三层前向，三张账单 <a class="header-anchor" href="#三层前向-三张账单" aria-label="Permalink to &quot;三层前向，三张账单&quot;">​</a></h3><p>实验室：剪辑上的 EMF + 3D 胶，校准用。OPC：全芯片紧凑，必须在掩模数据准备窗口内收敛。LRC：比 OPC 更稀的过程角，但仍是全场或准全场。三者共用模型版本，不能各算各的几何。</p><p><span class="marginnote">碎片并行不等于线性加速：热区迭代、掩模规则回修和跨碎片 jog 会把尾延迟拉长。看 P95 墙钟，不只看平均 TFLOPS。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>成本粗账：场面积 / 碎片面积 × 过程角 × 波长/偏振通道 × 每碎片卷积。SOCS 截断、核半径、刻蚀核层数都是旋钮。GPU 把卷积变便宜，不把 EMF 变成全芯片。抽样策略：规则阵列用周期模型；二维库、SRAM、切线用加密 clips。与 <a href="/litho/domain-decomposition-mask">域分解</a> 的关系：分解降低单块 EMF，仍盖不住 10<sup>11</sup> 量级的边。</p><p><span class="marginnote">数字实例：按 100 μm × 100 μm 切碎片，一个 26 mm × 33 mm 的场就是 26 000/100 × 33 000/100 = 260 × 330 ≈ 8.6 万块碎片；再乘十来个过程角和两三个波长/偏振通道，卷积次数轻松上到百万级——这就是「面积 × 角度」账单里每一项怎么长出来的。</span></p><p><span class="marginnote">术语翻译：SOCS（源–瞳相干系数序列）可以想象成「预制菜」——把光源每一点和光瞳每一点的无穷组合，提前压缩成几十个现成的卷积核；全芯片仿真只负责按碎片「加热复用」，不再回锅炒生料。核截断就是决定买几道预制菜。</span></p><p>工程合同写清：OPC 允许的核、LRC 的 PV 点集、热区才升级严格。模型残差课已经要求保持集；本课补的是保持集也必须能在预算内重跑。</p><p>签核日历比集群峰值更硬：掩模数据准备窗口一关，未扫完的角等于没签。故过程角集合要按层风险分级——金属二维层多角，周期鳍少角——而不是全球同一套 FEM 点。Mack 把模型分层写成工程常识；Levinson 把签核写成可交货日期。本课把两者乘在一起。掩模数据准备窗口（书写机排队、fracture、MPC）是外生截止：仿真若吃掉窗口，版就晚到，产能损失比「模型再准一纳米」更大。因此算力账要和掩模周期同一张日历，而不是只报集群利用率。</p>',15)),(e(),A(s,null,{default:E(()=>[r(i,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIELD%5B%22%E5%9C%BA%EF%BC%9A26%20mm%20%C3%97%2033%20mm%22%5D%20--%3E%20CLIPS%5B%22%E9%99%A4%E4%BB%A5%E7%A2%8E%E7%89%87%E9%9D%A2%E7%A7%AF%20%E2%86%92%20%E7%A2%8E%E7%89%87%E6%95%B0%22%5D%0A%20%20CLIPS%20--%3E%20ANG%5B%22%C3%97%20%E8%BF%87%E7%A8%8B%E8%A7%92%EF%BC%88%E6%8C%89%E5%B1%82%E9%A3%8E%E9%99%A9%E5%88%86%E7%BA%A7%EF%BC%89%22%5D%0A%20%20ANG%20--%3E%20CHAN%5B%22%C3%97%20%E6%B3%A2%E9%95%BF%20%2F%20%E5%81%8F%E6%8C%AF%E9%80%9A%E9%81%93%22%5D%0A%20%20CHAN%20--%3E%20CONV%5B%22%C3%97%20%E6%AF%8F%E7%A2%8E%E7%89%87%20SOCS%20%E5%8D%B7%E7%A7%AF%E9%87%8F%22%5D%0A%20%20CONV%20--%3E%20BUD%7B%22%E8%83%BD%E5%9C%A8%E6%8E%A9%E6%A8%A1%E6%95%B0%E6%8D%AE%E5%87%86%E5%A4%87%E7%AA%97%E5%8F%A3%E5%86%85%E6%89%AB%E5%AE%8C%EF%BC%9F%22%7D%0A%20%20BUD%20--%20%22%E8%83%BD%22%20--%3E%20SIGN%5B%22%E6%8C%89%E6%97%B6%E7%AD%BE%E6%A0%B8%22%5D%0A%20%20BUD%20--%20%22%E4%B8%8D%E8%83%BD%22%20--%3E%20CUT%5B%22%E5%87%8F%E8%A7%92%20%2F%20%E5%87%8F%E7%A2%8E%E7%89%87%20%2F%20%E5%8F%AA%E7%BB%99%E7%83%AD%E5%8C%BA%E5%8D%87%E7%BA%A7%E4%B8%A5%E6%A0%BC%22%5D%0A%20%20CUT%20--%3E%20CONV%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[t("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"Hopkins TCC 把源–瞳变成若干 SOCS 核，复杂度从「每源点一次成像」降到「若干次卷积」。胶与刻蚀是边邻域算子，复杂度随核半径和多边形数走。曲线 ILT 增加控制点，MPC 再乘一层。全芯片可完成，是因为几何被设计规则先投影到「可核化」子集——下一课 LFD 正是减少核必须修补的坏邻域。",-1)),(e(),A(s,null,{default:E(()=>[r(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20RULE%5B%22%E8%AE%BE%E8%AE%A1%E8%A7%84%E5%88%99%E5%AD%90%E9%9B%86%22%5D%20--%3E%20CHIP%5B%22%E5%85%A8%E8%8A%AF%E7%89%87%E7%B4%A7%E5%87%91%E5%89%8D%E5%90%91%22%5D%0A%20%20CHIP%20--%3E%20OPC%5B%22OPC%20%E5%86%85%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20HOT%5B%22%E7%83%AD%E5%8C%BA%20clips%22%5D%20--%3E%20RIG%5B%22FDTD%20%2F%20RCWA%20%2F%203D%20%E8%83%B6%22%5D%0A%20%20RIG%20--%3E%20CAL%5B%22%E6%A0%A1%E5%87%86%E6%A0%B8%22%5D%0A%20%20CAL%20--%3E%20CHIP%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p>曲线掩模把多边形数换成样条控制点，卷积次数未必降，MPC 与 MRC 检查反而升。算力合同要单独给 ILT 层一行，不能沿用曼哈顿层的碎片小时。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>算力账不替代计量：核快而残差大，只是更快地签错。不编造某厂「一夜全芯片 FDTD」或未公开的加速比。EUV 随机蒙特卡洛不是全芯片默认。</p><p><span class="marginnote">常见误区：工期赶不上时，容易以为「换更准的严格模型把结果算对」就行。实际上严格电磁每块碎片慢几个量级，塞进内循环只会把交付日期推走；正确动作是分层——大多数边用紧凑核快扫，只有热区升级严格，同时用计量数据查核残差。</span></p><p>后课默认：全场签核走紧凑；严格解留校准与热区。设计若能少生成必须重仿真的图形，账单才进得去下一课的 LFD。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全芯片前向是紧凑核的面积 × 过程角账单，严格电磁不进内循环。</li><li>OPC、LRC、实验室三层共用版本，墙钟合同不同。</li><li>规则子集决定有多少边必须被核修补。</li><li>出处：计算光刻全芯片成本通称；Mack / Levinson 对模型分层的工程叙述。</li></ul>',7))])}const P=n(d,[["render",B]]);export{f as __pageData,P as default};
